import RAPIER from '@dimforge/rapier3d-compat';
import * as THREE from 'three';
import type { Vec3 } from '../contracts/math';
import type { IZone } from '../contracts/zones';
import type {
  HazardObstacle,
  Hole,
  MovingObstacle,
  ObstacleDescriptor,
  SurfaceDescriptor,
  SurfaceMaterial,
  TransformDescriptor,
} from '../courses/types';
import type { HoleSceneBuilder, HoleSceneResult } from '../core/HoleSceneBuilder';
import { ZoneManager } from '../gameplay/zones/ZoneManager';
import {
  createForceObstacle,
  createPad,
  createZone,
  isFieldObstacle,
  isForceObstacle,
  isHazardObstacle,
  isPadDescriptor,
} from '../obstacles/descriptors';
import type { PadObstacle } from '../obstacles/pads';
import { resolveSurface } from '../obstacles/surfaces';
import type { BallObstacle, BallSample } from '../obstacles/types';
import { addVec3, scaleVec3 } from '../obstacles/vec';
import { CollisionLayers, collisionGroups } from '../physics/CollisionLayers';
import type { PhysicsWorld } from '../physics/PhysicsWorld';
import { cappedVelocity, clamp } from '../physics/helpers';

const COURSE_GROUPS = collisionGroups(CollisionLayers.COURSE, CollisionLayers.BALL);
const OBSTACLE_GROUPS = collisionGroups(CollisionLayers.OBSTACLE, CollisionLayers.BALL);
const RAMP_THICKNESS = 0.35;
const HAZARD_DEPTH_MARGIN = 0.45;
const SURFACE_REACH = 0.6;
const DEFAULT_OBSTACLE_RESTITUTION = 0.4;
const BUMPER_RESTITUTION = 1.05;
const OBSTACLE_FRICTION = 0.4;
/** Kept below gravity so a field steers the ball instead of lifting a resting one off the floor. */
const MAX_FIELD_ACCELERATION = 8;
/** A ball that only drops onto a pad must not be relaunched by it forever. */
const PAD_TRIGGER_SPEED = 0.3;

/** Constant rolling deceleration (m/s^2) per material; mirrors the model BotPlanner scores with. */
const DECELERATION: Record<SurfaceMaterial, number> = {
  green: 3.4,
  rough: 6.4,
  sand: 11,
  ice: 0.85,
  wood: 3,
  stone: 3.9,
  metal: 2.6,
};
const OFF_SURFACE_DECELERATION = 7.5;

interface Area {
  minX: number;
  maxX: number;
  minZ: number;
  maxZ: number;
  top: number;
}

interface SurfacePatch extends Area {
  deceleration: number;
}

interface HazardPatch extends Area {
  obstacle: HazardObstacle;
  zone: IZone;
}

interface Mover {
  body: RAPIER.RigidBody;
  object: THREE.Object3D | undefined;
  base: THREE.Vector3;
  axis: THREE.Vector3;
  baseRotation: THREE.Quaternion;
  motion: MovingObstacle['motion'];
}

/** What the sensor volumes want done to the ball after one fixed step. */
export interface BallEffect {
  /** Velocity to write back; equal to the sampled one when nothing acted. */
  velocity: Vec3;
  /** Set when a teleporter moved the ball. */
  position?: Vec3;
  clearAngularVelocity?: boolean;
  /** False when no volume touched the ball, so callers can skip the write. */
  changed: boolean;
  /** Ids of the volumes that acted, in the order they were applied. */
  sources: string[];
}

export interface HazardResolution {
  resetPosition: Vec3;
  penaltyStrokes: number;
}

const isMoving = (obstacle: ObstacleDescriptor): obstacle is MovingObstacle =>
  obstacle.type === 'spinner' || obstacle.type === 'windmill' || obstacle.type === 'gate' || obstacle.type === 'platform';

function scaledSize(size: Vec3, transform: TransformDescriptor): THREE.Vector3 {
  const scale = transform.scale;
  return new THREE.Vector3(size.x * (scale?.x ?? 1), size.y * (scale?.y ?? 1), size.z * (scale?.z ?? 1));
}

function rotationOf(transform: TransformDescriptor): THREE.Quaternion {
  const rotation = transform.rotation;
  return rotation
    ? new THREE.Quaternion(rotation.x, rotation.y, rotation.z, rotation.w)
    : new THREE.Quaternion();
}

function areaOf(position: Vec3, size: THREE.Vector3): Area {
  return {
    minX: position.x - size.x / 2,
    maxX: position.x + size.x / 2,
    minZ: position.z - size.z / 2,
    maxZ: position.z + size.z / 2,
    top: position.y + size.y / 2,
  };
}

const contains = (area: Area, x: number, z: number): boolean =>
  x >= area.minX && x <= area.maxX && z >= area.minZ && z <= area.maxZ;

/**
 * Runtime side of a hole: meshes from the scene builder plus the Rapier colliders,
 * kinematic movers and hazard volumes that the same descriptors imply.
 *
 * Walls, bumpers, pillars and the kinematic movers are solid. Everything that the
 * course data describes as a volume - hazards, teleporters, fans, conveyors, pads,
 * gravity and magnet fields - stays collider free and acts through `applyBallEffects`
 * and `hazardAt`, so a lava pool or a belt never behaves like a wall.
 */
export class HoleRuntime {
  readonly group: THREE.Group;

  private readonly scene: HoleSceneResult;
  private readonly bodies: RAPIER.RigidBody[] = [];
  private readonly movers: Mover[] = [];
  private readonly surfaces: SurfacePatch[] = [];
  private readonly hazards: HazardPatch[] = [];
  private readonly forces: BallObstacle[] = [];
  private readonly pads: PadObstacle[] = [];
  private readonly fields: IZone[] = [];
  private readonly fieldManager = new ZoneManager();
  private readonly tmpVector = new THREE.Vector3();
  private readonly tmpQuaternion = new THREE.Quaternion();
  private elapsed = 0;

  constructor(
    private readonly physics: PhysicsWorld,
    readonly hole: Hole,
    builder: HoleSceneBuilder,
  ) {
    this.scene = builder.build(hole);
    this.group = this.scene.group;
    for (const surface of hole.surfaces) this.addSurface(surface);
    for (const obstacle of hole.obstacles) this.addObstacle(obstacle);
  }

  get moverCount(): number {
    return this.movers.length;
  }

  /** Rigid bodies this hole owns; volumes add none, which is what keeps them passable. */
  get bodyCount(): number {
    return this.bodies.length;
  }

  get sensorCount(): number {
    return this.forces.length + this.pads.length + this.fields.length + this.hazards.length;
  }

  /** Advances kinematic obstacles and keeps their meshes in sync with the bodies. */
  update(dt: number): void {
    this.elapsed += Math.max(0, dt);
    for (const mover of this.movers) {
      if (mover.motion.kind === 'rotate') {
        const angle = (mover.motion.phase ?? 0) + this.elapsed * mover.motion.speed;
        this.tmpQuaternion.setFromAxisAngle(mover.axis, angle).multiply(mover.baseRotation);
        mover.body.setNextKinematicRotation({
          x: this.tmpQuaternion.x,
          y: this.tmpQuaternion.y,
          z: this.tmpQuaternion.z,
          w: this.tmpQuaternion.w,
        });
        mover.object?.quaternion.copy(this.tmpQuaternion);
        continue;
      }
      const phase = this.elapsed * mover.motion.speed + (mover.motion.phase ?? 0);
      const offset = Math.sin(phase) * (mover.motion.distance ?? 1);
      this.tmpVector.copy(mover.axis).multiplyScalar(offset).add(mover.base);
      mover.body.setNextKinematicTranslation({ x: this.tmpVector.x, y: this.tmpVector.y, z: this.tmpVector.z });
      mover.object?.position.copy(this.tmpVector);
    }
  }

  /**
   * One fixed step of the sensor volumes: force obstacles first (belts, fans and
   * teleporters), then the impulse pads, then the force fields. The caller writes the
   * resulting velocity - and the teleport target, when one fired - back onto the body.
   */
  applyBallEffects(sample: BallSample, dt: number, mass: number): BallEffect {
    const effect: BallEffect = { velocity: { ...sample.velocity }, changed: false, sources: [] };
    if (dt <= 0) return effect;
    const context = { dt, elapsed: this.elapsed };
    let position: Vec3 = { ...sample.position };

    for (const force of this.forces) {
      const result = force.update({ position, velocity: effect.velocity, radius: sample.radius }, context);
      if (!result) continue;
      effect.sources.push(result.obstacleId);
      effect.changed = true;
      if (result.teleport) {
        position = { ...result.teleport.position };
        effect.position = { ...result.teleport.position };
        effect.velocity = { ...result.teleport.velocity };
        effect.clearAngularVelocity = result.teleport.clearAngularVelocity;
        continue;
      }
      if (result.deltaVelocity) effect.velocity = addVec3(effect.velocity, result.deltaVelocity);
    }

    if (Math.hypot(effect.velocity.x, effect.velocity.z) >= PAD_TRIGGER_SPEED) {
      for (const pad of this.pads) {
        const hit = pad.update(position, effect.velocity, this.elapsed);
        if (!hit) continue;
        effect.velocity = hit.velocity;
        effect.changed = true;
        effect.sources.push(hit.padId);
      }
    }

    if (mass > 0 && this.fields.length > 0) {
      const field = this.fieldManager.calculateForces(position, effect.velocity, mass);
      const acceleration = cappedVelocity(scaleVec3(field, 1 / mass), MAX_FIELD_ACCELERATION);
      if (acceleration.x !== 0 || acceleration.y !== 0 || acceleration.z !== 0) {
        effect.velocity = addVec3(effect.velocity, scaleVec3(acceleration, dt));
        effect.changed = true;
      }
    }

    return effect;
  }

  /** Clears the one shot state of teleporters and pad cooldowns; call it per turn. */
  resetObstacles(): void {
    for (const force of this.forces) force.reset();
    for (const pad of this.pads) pad.reset();
  }

  /** Rolling deceleration of the surface under the ball, or a harsh value off the course. */
  decelerationAt(position: Vec3): number {
    let best: SurfacePatch | undefined;
    for (const patch of this.surfaces) {
      if (!contains(patch, position.x, position.z)) continue;
      if (patch.top > position.y + SURFACE_REACH) continue;
      if (!best || patch.top > best.top) best = patch;
    }
    return best?.deceleration ?? OFF_SURFACE_DECELERATION;
  }

  hazardAt(position: Vec3): HazardObstacle | undefined {
    for (const patch of this.hazards) {
      if (!contains(patch, position.x, position.z)) continue;
      if (position.y <= patch.top + HAZARD_DEPTH_MARGIN) return patch.obstacle;
    }
    return undefined;
  }

  /**
   * Penalty and respawn point the hazard zone dictates; water costs one stroke, lava two
   * unless the descriptor says otherwise. Out of bounds (no hazard) costs a single stroke.
   */
  resolveHazard(hazard: HazardObstacle | undefined, lastSafePosition: Vec3): HazardResolution {
    const patch = hazard ? this.hazards.find((entry) => entry.obstacle.id === hazard.id) : undefined;
    if (!patch) {
      return {
        resetPosition: { ...(hazard?.resetPosition ?? lastSafePosition) },
        penaltyStrokes: hazard?.penaltyStrokes ?? 1,
      };
    }
    const resolved = patch.zone.resolveHazard(lastSafePosition);
    return { resetPosition: { ...resolved.resetPosition }, penaltyStrokes: resolved.penaltyStrokes };
  }

  dispose(): void {
    for (const body of this.bodies) this.physics.world.removeRigidBody(body);
    this.bodies.length = 0;
    this.movers.length = 0;
    this.surfaces.length = 0;
    this.hazards.length = 0;
    this.forces.length = 0;
    this.pads.length = 0;
    for (const zone of this.fields) this.fieldManager.removeZone(zone.id);
    this.fields.length = 0;
    this.group.removeFromParent();
    this.scene.dispose();
  }

  private addSurface(surface: SurfaceDescriptor): void {
    const size = scaledSize(surface.size, surface.transform);
    const position = surface.transform.position;
    const properties = resolveSurface(surface);
    const rotation = rotationOf(surface.transform);
    let half = new THREE.Vector3(size.x / 2, size.y / 2, size.z / 2);

    // A ramp descriptor means \"rise size.y over size.z\": tilt a slab and match the mesh to it.
    if (surface.shape === 'ramp' && !surface.transform.rotation && size.z > 0.01) {
      const length = Math.hypot(size.y, size.z);
      rotation.setFromAxisAngle(new THREE.Vector3(1, 0, 0), -Math.atan2(size.y, size.z));
      half = new THREE.Vector3(size.x / 2, RAMP_THICKNESS / 2, length / 2);
      const mesh = this.group.getObjectByName(surface.id);
      if (mesh) {
        mesh.quaternion.copy(rotation);
        mesh.scale.set(size.x, RAMP_THICKNESS, length);
      }
    }

    const body = this.physics.world.createRigidBody(
      RAPIER.RigidBodyDesc.fixed()
        .setTranslation(position.x, position.y, position.z)
        .setRotation({ x: rotation.x, y: rotation.y, z: rotation.z, w: rotation.w }),
    );
    const collider =
      surface.shape === 'cylinder'
        ? RAPIER.ColliderDesc.cylinder(half.y, Math.max(half.x, half.z))
        : RAPIER.ColliderDesc.cuboid(half.x, half.y, half.z);
    this.physics.world.createCollider(
      collider
        .setFriction(properties.friction)
        .setRestitution(properties.restitution)
        .setCollisionGroups(COURSE_GROUPS),
      body,
    );
    this.bodies.push(body);

    const base = DECELERATION[surface.material] ?? DECELERATION.green;
    const deceleration =
      surface.friction === undefined ? base : base * clamp(surface.friction / 0.6, 0.35, 3);
    this.surfaces.push({ ...areaOf(position, size), deceleration });
  }

  private addObstacle(obstacle: ObstacleDescriptor): void {
    if (obstacle.enabled === false) return;
    const size = scaledSize(obstacle.size, obstacle.transform);
    const position = obstacle.transform.position;

    if (isHazardObstacle(obstacle)) {
      this.hazards.push({ ...areaOf(position, size), obstacle, zone: createZone(obstacle) });
      return;
    }
    if (isForceObstacle(obstacle)) {
      this.forces.push(createForceObstacle(obstacle));
      return;
    }
    if (isPadDescriptor(obstacle)) {
      this.pads.push(createPad(obstacle));
      return;
    }
    if (isFieldObstacle(obstacle)) {
      const zone = createZone(obstacle);
      this.fields.push(zone);
      this.fieldManager.addZone(zone);
      return;
    }

    const rotation = rotationOf(obstacle.transform);
    const half = new THREE.Vector3(size.x / 2, size.y / 2, size.z / 2);
    const moving = isMoving(obstacle);
    const descriptor = moving ? RAPIER.RigidBodyDesc.kinematicPositionBased() : RAPIER.RigidBodyDesc.fixed();
    const body = this.physics.world.createRigidBody(
      descriptor
        .setTranslation(position.x, position.y, position.z)
        .setRotation({ x: rotation.x, y: rotation.y, z: rotation.z, w: rotation.w }),
    );
    const override = 'restitution' in obstacle ? obstacle.restitution : undefined;
    const restitution =
      typeof override === 'number'
        ? override
        : obstacle.type === 'bumper'
          ? BUMPER_RESTITUTION
          : DEFAULT_OBSTACLE_RESTITUTION;
    const collider =
      obstacle.type === 'pillar'
        ? RAPIER.ColliderDesc.cylinder(half.y, Math.max(half.x, half.z))
        : RAPIER.ColliderDesc.cuboid(half.x, half.y, half.z);
    this.physics.world.createCollider(
      collider
        .setFriction(OBSTACLE_FRICTION)
        .setRestitution(restitution)
        .setCollisionGroups(OBSTACLE_GROUPS),
      body,
    );
    this.bodies.push(body);

    if (!moving) return;
    const axis = new THREE.Vector3(obstacle.motion.axis.x, obstacle.motion.axis.y, obstacle.motion.axis.z);
    if (axis.lengthSq() < 1e-8) axis.set(0, 1, 0);
    else axis.normalize();
    this.movers.push({
      body,
      object: this.group.getObjectByName(obstacle.id),
      base: new THREE.Vector3(position.x, position.y, position.z),
      axis,
      baseRotation: rotation.clone(),
      motion: obstacle.motion,
    });
  }
}
